export const bassNotes=[29,31,36,39,41,44,32,27];
export const leadNotes=[65,68,72,75,77,79,80,63];
export const noteName=n=>['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][n%12]+(Math.floor(n/12)-1);
const hz=n=>440*2**((n-69)/12);
export class Engine{
 constructor(ctx,state){this.ctx=ctx;this.state=state;this.sources=new Set();this.input=ctx.createGain();this.compressor=ctx.createDynamicsCompressor();this.compressor.threshold.value=-14;this.compressor.knee.value=20;this.compressor.ratio.value=6;this.compressor.attack.value=.003;this.compressor.release.value=.18;this.master=ctx.createGain();this.analyser=ctx.createAnalyser();this.analyser.fftSize=2048;this.input.connect(this.compressor);this.compressor.connect(this.master);this.master.connect(this.analyser);this.analyser.connect(ctx.destination);this.delay=ctx.createDelay(2);this.feedback=ctx.createGain();this.wet=ctx.createGain();this.delay.connect(this.feedback);this.feedback.connect(this.delay);this.delay.connect(this.wet);this.wet.connect(this.input);this.noise=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate);let seed=12345;const d=this.noise.getChannelData(0);for(let i=0;i<d.length;i++){seed=(1664525*seed+1013904223)>>>0;d[i]=seed/2147483648-1;}this.update();}
 update(){const t=this.ctx.currentTime;this.master.gain.setTargetAtTime(this.state.master/100*.8,t,.025);this.delay.delayTime.setTargetAtTime(60/this.state.bpm*.75,t,.02);this.feedback.gain.setTargetAtTime(.16+this.state.space/100*.48,t,.03);this.wet.gain.setTargetAtTime(this.state.space/100*.55,t,.03);}
 source(node,end,cleanup=[]){this.sources.add(node);node.onended=()=>{this.sources.delete(node);node.disconnect();cleanup.forEach(n=>n.disconnect());};node.stop(end);return node;}
 env(t,length,level,dest=this.input){const g=this.ctx.createGain();g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,level),t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+length);g.connect(dest);return g;}
 tone(t,freq,type,length,level,dest=this.input,detune=0){const o=this.ctx.createOscillator();o.type=type;o.frequency.setValueAtTime(freq,t);o.detune.value=detune;const g=this.env(t,length,level,dest);o.connect(g);o.start(t);this.source(o,t+length+.03,dest===this.input?[g]:[g,dest]);return o;}
 hiss(t,length,level,freq,type='highpass'){const n=this.ctx.createBufferSource();n.buffer=this.noise;const f=this.ctx.createBiquadFilter();f.type=type;f.frequency.value=freq;const g=this.env(t,length,level);n.connect(f);f.connect(g);n.start(t);this.source(n,t+length+.02,[f,g]);}
 trigger(id,value,t){const s=this.state,step=60/s.bpm/4,funk=s.genre==='funk';
 if(id==='kick'){const length=funk?.13+s.punch/100*.13:.2+s.punch/100*.28;const o=this.tone(t,funk?170:155,'sine',length,.9);o.frequency.exponentialRampToValueAtTime(funk?54:s.genre==='dnb'?44:48,t+(funk?.045:.07));this.hiss(t,.012,funk?.1:.07,6000);}
 if(id==='clap'){for(let i=0;i<3;i++)this.hiss(t+i*.012,i===2?(funk?.095:.15):.022,.19,funk?1800:1300,'bandpass');this.tone(t,funk?340:180,'triangle',funk?.045:.08,funk?.16:.08);}
 if(id==='hat'){this.hiss(t,funk?.03:.045,funk?.1:.14,funk?6500:8500);}
 if(id==='open'){if(funk){const tom=this.tone(t,230,'sine',.18,.48);tom.frequency.exponentialRampToValueAtTime(95,t+.13);this.tone(t,360,'triangle',.055,.07);this.hiss(t,.018,.055,2200,'bandpass');}else this.hiss(t,.19,.12,6500);}
 if(funk&&id==='bass'){const freq=hz(bassNotes[value-1]),length=step*2.2;const sub=this.tone(t,freq*1.35,'sine',length,.46);sub.frequency.exponentialRampToValueAtTime(freq,t+.045);const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=110+s.cutoff*13;filter.connect(this.input);this.tone(t,freq,'triangle',length,.15,filter);return;}
 if(funk&&id==='synth'){const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=750+s.cutoff*32;filter.connect(this.input);filter.connect(this.delay);this.tone(t,hz(leadNotes[value-1]),'square',step*.7,.095,filter);return;}
 if(id==='bass'){const n=bassNotes[value-1],freq=hz(n);const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.Q.value=s.genre==='techno'?10:4;const low=90+s.cutoff/100*3200;filter.frequency.setValueAtTime(low*2,t);filter.frequency.exponentialRampToValueAtTime(Math.max(60,low*.55),t+step*.9);filter.connect(this.input);const length=step*(s.genre==='dnb'?2.5:1.2);this.tone(t,freq,s.genre==='dnb'?'sawtooth':'sawtooth',length,.23,filter,-5);if(s.genre==='dnb')this.tone(t,freq,'sawtooth',length,.18,filter,7);this.tone(t,freq,'sine',length,.28);}
 if(id==='synth'){const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1200+s.cutoff*35;filter.Q.value=.7;filter.connect(this.input);filter.connect(this.delay);const freq=hz(leadNotes[value-1]);const length=step*(s.genre==='trance'?2.3:1.6);this.tone(t,freq,'sawtooth',length,.09,filter,-9);this.tone(t,freq,'sawtooth',length,.09,filter,9);if(s.genre==='house')this.tone(t,freq*2**(7/12),'triangle',length,.07,filter);}
 }
 step(index,t){for(const track of this.state.tracks){if(!track.muted&&track.steps[index])this.trigger(track.id,track.steps[index],t);}}
 silence(){for(const source of this.sources){try{source.stop(this.ctx.currentTime);}catch{}}this.feedback.gain.cancelScheduledValues(this.ctx.currentTime);this.feedback.gain.value=0;}
 dispose(){this.silence();this.input.disconnect();this.delay.disconnect();this.feedback.disconnect();this.wet.disconnect();this.master.disconnect();this.analyser.disconnect();this.compressor.disconnect();}
}
export async function renderWav(state){const rate=44100,duration=60/state.bpm*16+2;const ctx=new OfflineAudioContext(2,Math.ceil(duration*rate),rate);const engine=new Engine(ctx,state);const step=60/state.bpm/4;for(let i=0;i<64;i++)engine.step(i%16,.03+i*step);const buffer=await ctx.startRendering();const bytes=new ArrayBuffer(44+buffer.length*4),view=new DataView(bytes);const str=(offset,s)=>{for(let i=0;i<s.length;i++)view.setUint8(offset+i,s.charCodeAt(i));};str(0,'RIFF');view.setUint32(4,36+buffer.length*4,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,2,true);view.setUint32(24,rate,true);view.setUint32(28,rate*4,true);view.setUint16(32,4,true);view.setUint16(34,16,true);str(36,'data');view.setUint32(40,buffer.length*4,true);const left=buffer.getChannelData(0),right=buffer.getChannelData(1);for(let i=0;i<buffer.length;i++){view.setInt16(44+i*4,Math.max(-1,Math.min(1,left[i]))*32767,true);view.setInt16(46+i*4,Math.max(-1,Math.min(1,right[i]))*32767,true);}return new Blob([bytes],{type:'audio/wav'});}
